    'producer.card.OPR_001.what_detail': "路線{route}{dir}（{days}）では、{from}発の次の便は{to}発です。{gap}の間、便がありません。上限は{limit}です。",
    'producer.card.OPR_003.what_detail': "路線{route}{dir}（{days}）では、{stop}を{from}と{to}に出る2便の間隔が{gap}しかありません。乗客にはほぼ同時に来るように見えます。",
    'producer.card.OPR_004.what_detail': "路線{route}は平日のみ運行し、土曜・日曜の便はありません。参考情報です。",
    'producer.card.OPR_005.what_sparse': "路線{route}{dir}（{days}）の便は平均{hw}分ごとに出発します（{first}–{last}、{n}便）。同種の路線は通常{median}分ごとです。この路線は同種よりかなり少ないです。",
    'producer.card.OPR_005.what_dense': "路線{route}{dir}（{days}）の便は平均{hw}分ごとに出発します（{first}–{last}、{n}便）。同種の路線は通常{median}分ごとです。この路線は同種よりかなり多いです。",
    'producer.card.OPR_006.what_detail': "{trip}は停留所が1つだけです（{stop}）。この便ではどこへも移動できません。",
    'producer.card.OPR_007.what_detail': "{trip}は{stop}を{n}回通ります。他の停留所を経て同じ停留所に戻るのは、通常、停留所順序の入力誤りです。",
    'producer.card.OPR_008.what_detail': "{trip}では{n}区間で速度が上限を超えています。最高速度は{max} km/h（上限{limit} km/h）です。通常、停留所の時刻または位置の誤りが原因です。",
    'producer.card.OPR_009.what_detail': "路線{route}には深夜便が{n}便あり、{first} – {last}に出発します。参考情報です。",
    'producer.card.OPR_009.what_one': "路線{route}には深夜便が{n}便あり、{first}に出発します。参考情報です。",
    'producer.card.OPR_010.what_wheelchair': "路線{route}では、{yes}便が車いす対応、{no}便が非対応と記載されています。同じ路線で情報が異なると乗客が誤解する可能性があります。",
    'producer.card.OPR_010.what_bikes': "路線{route}では、{yes}便が自転車可、{no}便が不可です。同じ路線で情報が異なると乗客が誤解する可能性があります。",
    'producer.card.OPR_011.what_detail': "カレンダー{svc}には運行日がまったくありません。これを使う便は一度も運行しません。",
    'producer.card.OPR_012.what_detail': "カレンダー{svc}は{from}から{to}までの間の{gap}日間、運行がありません。",
    'producer.card.OPR_013.what_detail': "路線{route}には{dir}の便しかなく、反対方向が定義されていません。一方向または循環路線なら問題ありません。",
    'producer.card.OPR_014.what_detail': "乗換ルールの時間指定乗換{n}件の平均は{avg}です（上限10分）。最も長いものを下表と地図に示します。",
    'producer.card.OPR_015.what_detail': "路線{route}の両方向の便が同じ経路形状（{shape}）を使っています。復路は地図上で往路と同じ線に表示されます。参考情報です。",
    'producer.card.OPR_016.what_detail': "データセットのどのカレンダーにも運行日がありません。乗客向けアプリに便は一つも表示されません。",
    'producer.card.OPR_017.what_detail': "{trip}は{m}メートルしか走りません（{from} → {to}、{n}停留所）。これほど短い便は通常、停留所や位置の誤りです。",
    'producer.card.OPR_019.what_detail': "路線{route}では{n}日に複数のカレンダーが同時に運行しています（例：{dates}）。その日は便が二重に表示されることがあります。",
    'producer.card.OPR_020.what_detail': "路線{route}では特別日{n}日に複数のカレンダーが同時に運行しています（例：{dates}）。その日は便が二重に表示されることがあります。",
    'producer.card.OPR_021.what_detail': "路線{route}では特別日{n}日に特別ダイヤ（{override}）と通常ダイヤ（{base}）の両方が運行しています（初日{first}）。その日は便が二重に表示されます。",
    'producer.card.OPR_022.what_detail': "路線{route}では特別日{n}日に通常ダイヤ（{base}）が運行し、特別ダイヤ（{override}）が適用されていません（初日{first}）。",
    'producer.card.OPR_023.what_detail': "路線{route}では特別日{n}日に通常ダイヤ（{base}）も特別ダイヤ（{override}）も運行していません（初日{first}）。その日は便が表示されません。",
    'producer.card.OPR_024.what_detail': "路線{route}はカレンダー{svc}に{n}便あります（上限{limit}）。1つのカレンダーにこれほど多い便は、通常2つのダイヤや複数路線の統合が原因です。",
    'producer.card.OPR_025.what_detail': "便の平均所要時間は{avg}秒です。これほど短いのは通常、時刻の出力誤りです。最も短い便を下表に示します。",
