    'producer.card.SHP_014.what_start': "{shape}の始点は、便の最初の停留所「{stop}」から{dist}離れています。線が停留所の手前か先から始まっています。",
    'producer.card.SHP_014.what_end': "{shape}の終点は、便の最後の停留所「{stop}」から{dist}離れています。線が停留所の手前で終わるか、通り過ぎています。",
    'producer.card.SHP_015.what_detail': "{shape}は{km} kmありますが点は{n}個だけです。線は道に沿わず点の間を直線で結びます。点を地図に赤で示しています。",
    'producer.card.SHP_016.what_detail': "{shape}が逆向きに描かれています。便は「{stop}」から始まりますが、この停留所は線の始点ではなく終点付近にあります。アプリは進行方向を誤って表示します。",
    'producer.card.SHP_017.what_detail': "{trip}は「{stop}」に、線上で前の停留所より手前の地点で停車しています。停留所の順序が形状と合いません。",
    'producer.card.SHP_017.what_shape': "形状：{shape}。ループや同じ道を2回通る路線なら通常の場合があります。",
    'producer.card.SHP_018.what_detail': "{shape}を使う便はありません。",
    'producer.card.SHP_018.what_size': "{n}点、長さ{dist}の形状です。",
    'producer.card.SHP_019.what_detail': "{shape}は{n}便に割り当てられていますが、どの便にも停車時刻がありません。乗客にはこれらの便が表示されません。",
    'producer.card.SHP_020.what_detail': "{shape}：線が{a}番目と{b}番目の点で同じ場所を通ります。間の点がループや折り返しを作っている可能性があります。地図に赤丸で示しています。",
    'producer.card.SHP_020.what_plain': "{shape}が同じ場所を2回通ります。地図に赤丸で示しています。",
    'producer.card.SHP_020.what_repeat': "同じ点が{n}の形状にあります（駅や分岐器の形状の可能性）。",
    'producer.card.SHP_020.what_many': "{n}の経路形状で同じ場所を2回通る点があります。多くは測定のゆらぎです。乗客への影響はありません。",
    'producer.card.SHP_021.what_detail': "{shape}：{line}行目の点の走行距離が「{value}」です。0以上の数値にしてください。",
    'producer.card.SHP_022.what_detail': "「{stop}」は{shape}の{n}か所に近接しています。停車時刻に距離がないため、アプリが停留所を線の誤った部分に置く場合があります。",
    'producer.card.SHP_023.what_detail': "{shape}：同じ点が同じ距離（{dist}）で連続して2回書かれています。乗客への影響はありません。",
    'producer.card.SHP_024.what_detail': "停車時刻に書かれた「{stop}」の距離（{sdt}）は、停留所から{dist}離れた線上の地点を指しています（{shape}）。アプリは停留所を線の誤った位置に置きます。距離が指す地点を地図に赤で示しています。",
    'producer.card.SHP_025.what_detail': "{trip}の停車時刻の距離は{max}まで達しますが、{shape}の全長は{total}です。2つのファイルで距離の単位が異なる可能性があります。",
    'producer.card.SHP_025.what_unit': "差は約1,000倍です。一方がメートル、もう一方がキロメートルの可能性があります。",
    'producer.card.SHP_026.what_detail': "{shape}は{n}点あります（上限{limit}）。これほど詳細な形状は地図を遅くします。乗客に見える影響はありません。",
    'producer.card.SHP_028.what_detail': "{shape}：連続する2点が同じ距離（{dist}）を持ちますが、{apart}離れています。線は進むのに距離が増えていません。",
    'producer.card.SHP_029.what_detail': "{shape}：連続する2点が同じ距離（{dist}）を持ち、間はわずか{apart}です。おそらく同じ点の重複です。",
    'producer.card.SHP_030.what_detail': "{shape}：{k}便が停車時刻で距離を使っていますが、形状の{total}点のうち{missing}点に距離がありません。アプリは停留所を線上に正しく置けません。",
